// Accent palettes for the runtime accent selector.
// Keys map 1:1 to the `--p-primary-*` CSS vars generated by the Aura preset,
// so switching accent = overriding those vars on <html>. Works in both
// light and dark mode (primary scale is scheme-independent).

export interface AccentScale {
  50: string;
  100: string;
  200: string;
  300: string;
  400: string;
  500: string;
  600: string;
  700: string;
  800: string;
  900: string;
  950: string;
}

export interface Accent {
  id: string;
  label: string;
  /** Dot color shown in the selector. */
  dot: string;
  scale: AccentScale;
}

