export const DEFAULT_ACCENT_ID = 'sunset';

const STEPS = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950] as const;

/** Override `--p-primary-*` vars. Pass null/undefined to reset to preset default. */
export function applyAccent(id: string | null | undefined) {
  const root = document.documentElement;
  const accent = ACCENTS.find((a) => a.id === id);
  for (const step of STEPS) {
    const varName = `--p-primary-${step}`;
    if (accent) root.style.setProperty(varName, accent.scale[step]);
    else root.style.removeProperty(varName);
  }
}
